def comps_all(I,v):
    H,W=len(I),len(I[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if I[i][j]==v and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and I[ny][nx]==v and (ny,nx) not in seen:
